import{_ as t,o,c as s,a2 as a}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"40 - Logout And Session Lifecycle","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/40-logout-and-session-expiry.md","filePath":"developers/design-documentation/40-logout-and-session-expiry.md"}'),r={name:"developers/design-documentation/40-logout-and-session-expiry.md"};function d(i,e,n,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="_40-logout-and-session-lifecycle" tabindex="-1">40 - Logout And Session Lifecycle <a class="header-anchor" href="#_40-logout-and-session-lifecycle" aria-label="Permalink to &quot;40 - Logout And Session Lifecycle&quot;">​</a></h1><h2 id="session-types" tabindex="-1">Session Types <a class="header-anchor" href="#session-types" aria-label="Permalink to &quot;Session Types&quot;">​</a></h2><p>Tradeboard maintains separate but related state:</p><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td>Flask app session</td><td>Browser is authenticated to the local application</td></tr><tr><td>Active-session row</td><td>Device/IP/login/last-seen audit for the app session</td></tr><tr><td>Broker auth row</td><td>Installation&#39;s current broker and encrypted auth/feed tokens</td></tr><tr><td>Tradeboard API key</td><td>External/internal service authentication that resolves the broker row</td></tr></tbody></table><p>Multiple app devices share one broker auth row and one server-side broker market-data feed.</p><h2 id="login-and-heartbeat" tabindex="-1">Login And Heartbeat <a class="header-anchor" href="#login-and-heartbeat" aria-label="Permalink to &quot;Login And Heartbeat&quot;">​</a></h2><p>Successful app/broker login assigns <code>session_id</code> and registers an <code>active_sessions</code> row. The database caps the user at five rows, replaces an existing same-user/same-IP row, and removes the oldest at the cap.</p><p>The React app reads <code>/auth/session-status</code>. For logged-in sessions, that request touches <code>last_seen</code> at most once per 30 seconds using a timestamp in the signed Flask session. This makes the security dashboard liveness field meaningful without writing on every poll.</p><h2 id="broker-token-rollover" tabindex="-1">Broker Token Rollover <a class="header-anchor" href="#broker-token-rollover" aria-label="Permalink to &quot;Broker Token Rollover&quot;">​</a></h2><p>The default daily expiry time is 03:00 IST. <code>DISABLE_SESSION_EXPIRY=true</code> supports 24/7 crypto deployments. Request guards apply expiry and revoke broker access according to this policy.</p><p>Broker expiry does not necessarily invalidate the local app session. When <code>/auth/session-status</code> finds an authenticated browser but no usable broker token, it preserves <code>logged_in</code> and returns <code>broker_session_expired: true</code>. The UI can then render broker reconnect and <code>/auth/broker</code> can admit the user.</p><h2 id="multi-device-resume" tabindex="-1">Multi-Device Resume <a class="header-anchor" href="#multi-device-resume" aria-label="Permalink to &quot;Multi-Device Resume&quot;">​</a></h2><p>On resume, <code>upsert_auth()</code> compares decrypted broker/feed tokens plus broker and revoke state. If nothing material changed, it does not publish a teardown invalidation. This prevents a second browser login from disconnecting the feed used by the first device.</p><p>If tokens materially change or are revoked, cache/feed invalidation remains required.</p><h2 id="explicit-logout" tabindex="-1">Explicit Logout <a class="header-anchor" href="#explicit-logout" aria-label="Permalink to &quot;Explicit Logout&quot;">​</a></h2><p><code>GET</code>/<code>POST /auth/logout</code> clears the Flask session, revokes the broker auth row through <code>upsert_auth(username, &quot;&quot;, &quot;&quot;, revoke=True)</code>, drops the auth/feed/symbol caches, removes every active-session row for the user through <code>clear_user_sessions()</code>, and emits <code>force_logout</code> plus a zeroed <code>active_sessions_update</code>. It is an all-device logout, not a single-device one.</p><p>The route is deliberately NOT CSRF-exempt in <code>app.py</code>. The POST form is covered by Flask-WTF; the GET form, which Flask-WTF never validates, is covered inside the view by <code>_is_foreign_initiated()</code>, a <code>Sec-Fetch-Site</code> fetch-metadata check that aborts with 403 for any cross-site (or same-site but not same-origin) caller.</p><h2 id="account-security-events" tabindex="-1">Account Security Events <a class="header-anchor" href="#account-security-events" aria-label="Permalink to &quot;Account Security Events&quot;">​</a></h2><ul><li>Password change clears all active-session rows, emits <code>force_logout</code>, and clears the current cookie.</li><li>Password reset also calls <code>clear_user_sessions()</code>, emits <code>force_logout</code>, and pops the <code>reset_token</code>, <code>reset_email</code>, <code>reset_method</code>, and <code>email_reset_token</code> keys from the session.</li><li>Active-session APIs under auth and security are read-only; there is no documented endpoint for remotely revoking one selected device.</li></ul><h2 id="frontend-behavior" tabindex="-1">Frontend Behavior <a class="header-anchor" href="#frontend-behavior" aria-label="Permalink to &quot;Frontend Behavior&quot;">​</a></h2><p><code>AuthSync</code> restores user, broker, API key, app mode, capabilities, and active-session count. A normal unauthenticated response clears the Zustand stores. Network errors preserve existing state for the current render rather than forcing a false logout.</p><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>blueprints/auth.py</code></td><td>Session status, heartbeat, login, logout, password change</td></tr><tr><td><code>database/auth_db.py</code></td><td>ActiveSession model, cap, last-seen, token upsert/revocation</td></tr><tr><td><code>app.py</code></td><td>Daily expiry request guard and CSRF exemptions</td></tr><tr><td><code>utils/session.py</code></td><td>Protected blueprint checks</td></tr><tr><td><code>frontend/src/components/auth/AuthSync.tsx</code></td><td>SPA session restoration</td></tr><tr><td><code>frontend/src/stores/sessionStore.ts</code></td><td>Active-session count</td></tr></tbody></table>',23)])])}const b=t(r,[["render",d]]);export{p as __pageData,b as default};
